import Foundation

/// Difficulty tiers, mirroring monkeytype's english lists.
///
/// Each tier is a prefix of one frequency-ranked corpus, so `english 50` really
/// is the 50 most common words and `english 10k` widens outward from there.
enum WordList: String, CaseIterable, Identifiable, Codable {
    case english50
    case english200
    case english500
    case english1k
    case english5k
    case english10k

    var id: String { rawValue }

    var title: String {
        switch self {
        case .english50: return "english 50"
        case .english200: return "english 200"
        case .english500: return "english 500"
        case .english1k: return "english 1k"
        case .english5k: return "english 5k"
        case .english10k: return "english 10k"
        }
    }

    var count: Int {
        switch self {
        case .english50: return 50
        case .english200: return 200
        case .english500: return 500
        case .english1k: return 1000
        case .english5k: return 5000
        case .english10k: return 10000
        }
    }
}

/// The word pool.
///
/// GENERATED FILE — edit `tools/` and re-run `tools/build-wordlist.sh`.
///
/// The corpus is frequency-ranked (10000 most common English words),
/// filtered to 2-10 letters, validated against the system spell checker, and
/// scrubbed of profanity, slurs, sexual and anatomical content, drug slang,
/// brand names and web-corpus noise.
///
/// It ships inline because nothing on the system can rank words by frequency:
/// `/usr/share/dict/words` is alphabetical, so a "50" tier taken from it would
/// just be `a, aa, aal, aalii...`, and it is a 1934 dictionary that predates
/// "internet", "email" and "software".
enum Words {
    static let corpus: [String] = chunks
        .joined(separator: " ")
        .split(separator: " ")
        .map(String.init)

    /// A random word from the chosen tier, avoiding repeats where it can.
    static func random(for list: WordList, avoiding: Set<String> = []) -> String {
        guard !corpus.isEmpty else { return "word" }
        let limit = min(list.count, corpus.count)
        guard limit > 1 else { return corpus[0] }
        for _ in 0..<24 {
            let word = corpus[Int.random(in: 0..<limit)]
            if !avoiding.contains(word) { return word }
        }
        return corpus[Int.random(in: 0..<limit)]
    }

    /// A fresh queue, with no repeats inside it.
    static func randomQueue(count: Int, from list: WordList) -> [String] {
        var words: [String] = []
        for _ in 0..<max(1, count) {
            words.append(random(for: list, avoiding: Set(words)))
        }
        return words
    }

    /// 1,000 words per literal, so no single literal is enormous.
    private static let chunks: [String] = [
        "the of and to in for is on that by this with you it not or be are from at as your all have new more an was we will home can us about if my has free but our one other do no time they he up may what which their news out use any there see only so his when here who also now help get view first been would how were me some these its like service than find price date back top people had list name just over state year day into email two health world next used go work last most products music buy data make them should product system post her city add policy number such please available support message after best software then good video well where rights public books high school through each links she review years order very book items company read group need many user said does set under general research university mail full map reviews program life know games way days management part could great united hotel real item center must store travel comments made report off member details line before hotels did send right type because local those using results office education national car design take posted internet address community within states area want phone shipping reserved subject between forum family long based code show even black check special prices index being women much sign file link open today technology south case project same pages version section own found sports house related security both county photo game members power while care network down computer systems three total place end following him without per access think north resources current posts big media law control water history pictures size art personal since including guide shop directory board location change white text small rating rate government children during return students shopping account times sites level digital profile previous form events love old john main call hours image department title non insurance another why shall property class still money quality every listing content